import{_ as p,a as i,b as t,c as r,d as o,e as s}from"./chunks/c92378f4665bfa38d5bb.D5F0CFGw.js";import{_ as n,C as h,o as m,c,j as a,a as d,E as u,a6 as f}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"如何用AI真正赚到100万美元","description":"","frontmatter":{"title":"如何用AI真正赚到100万美元","originalTitle":"How To Actually Make $1 Million With AI","date":"2025-04-06","originalUrl":"https://thedankoe.com/letters/how-to-actually-make-1-million-with-ai/","minutes":9,"sourceHash":"d7166baa3de20343ce0938e1be23b15f943d508fa3fbf524140c7706912ad71f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-actually-make-1-million-with-ai/"}]]},"headers":[],"relativePath":"letters/how-to-actually-make-1-million-with-ai.md","filePath":"letters/how-to-actually-make-1-million-with-ai.md"}'),k={name:"letters/how-to-actually-make-1-million-with-ai.md"};function A(_,e,I,b,x,g){const l=h("ArticleMeta");return m(),c("div",null,[e[0]||(e[0]=a("h1",{id:"如何用ai真正赚到100万美元",tabindex:"-1"},[d("如何用AI真正赚到100万美元 "),a("a",{class:"header-anchor",href:"#如何用ai真正赚到100万美元","aria-label":'Permalink to "如何用AI真正赚到100万美元"'},"​")],-1)),u(l),e[1]||(e[1]=f('<p><a href="https://www.youtube.com/embed/z9dtU-xUX04?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我敢打赌,你点开这篇文章是想找一个快速赚钱的方法。</p><p>很抱歉要打破你的幻想,但你永远不会活在那样一个世界里。</p><p>永远永远永远都不会有那么一天,你只需要告诉一堆机器人去帮你赚钱,然后你就可以坐在那里,守着那些你不想改变的坏习惯,什么都不做。</p><p>事情不是这样运作的。</p><p>现实是,AI什么都没改变。</p><ul><li>你依然需要流量</li><li>你依然需要内容</li><li>你依然需要推广</li><li>你依然需要一个有价值的产品/服务</li><li>你依然需要客户画像</li><li>你依然需要落地页</li><li>你依然需要文案写作</li></ul><p>当然,你依然需要<em>理解</em>你在做什么,才能把上面这些事情很好地组织起来。</p><p>所以,不,这不是什么花里胡哨的新型AI商业模式,能让你免于学习商业的每一条原则。</p><p>AI改变的唯一一件事,是你完成上述事情的速度和质量。</p><p>但有意思的地方在这里:</p><p>我喜欢写内容和写书(比如我那本新出的小书<a href="https://thedankoe.com/purpose" target="_blank" rel="noreferrer">《目的与利润》(Purpose &amp; Profit)</a>,它是免费的PDF,现在你可以在Kortex里和它聊天了!(把PDF拖进对话框或你的资料库即可))。这才是我想投入时间去做的事。这是我的差异化优势——我的想法和新颖的视角。</p><p>然而,我并不喜欢做营销。如果我花足够的时间去激发创造力,我是能做好营销的,但要让自己真正在乎优化标题、线索获取、产品定位这些东西,实在是一种煎熬。我更愿意把我有限的创造性火力,花在我喜欢写的东西上。</p><p>在商业中,当你不喜欢做某件事时,聪明的做法是把它外包给某个人——或者现在,某个东西——能做得比你更好的人或物。</p><p>问题是,AI开箱即用并不是一个好的营销人员(或写手)。AI拥有的是海量的通用信息,需要被转化成具体的东西。</p><p>所以,如果你想把营销外包出去,你有两个选择:</p><ol><li>变得非常擅长营销,并创建你自己的AI系统。</li><li>找到一个擅长营销的人,理解其流程,然后使用他们的系统,这样你就能专注于你喜欢做的事情。</li></ol><p>说到这,我要说你很幸运!</p><p>因为我已经创建了一个AI系统,它能创造出比99%的创作者、企业,尤其是企业营销部门更好的客户画像、产品/服务方案、落地页和销售文案。</p><h3 id="如何赚到100万美元-通用方法" tabindex="-1">如何赚到100万美元(通用方法) <a class="header-anchor" href="#如何赚到100万美元-通用方法" aria-label="Permalink to &quot;如何赚到100万美元(通用方法)&quot;">​</a></h3><p>在开始之前,我们先来拆解一下几条通往年入100万美元的现实路径。</p><p>1,000,000美元 / 12 = 每月83,333美元</p><p>83,333美元 / 30 = 每天2,777美元</p><p>实现这个目标,有几种方式。</p><ul><li>每天卖出18个150美元的产品</li><li>每天卖出111份25美元的订阅</li><li>每隔一天拿下一个5000美元的客户</li><li>每4天拿下一个10,000美元的客户</li><li>两者结合。每周1-2个客户,再加上每天几笔产品销售。</li><li>或者任何其他能达到100万美元的组合与价格点。</li></ul><p>如果你走客户路线,过一段时间后你可能需要一个团队(或者把服务打包得足够标准化,能让你自己搞定履约)。</p><p>如果你走产品或订阅路线,比如软件或会员制,你就需要大量的流量。</p><p>你要怎么获得足够的流量,才能达成那么多的产品或服务销售?</p><p>以落地页2.5%的转化率来算,你需要每天有720人访问那个可以购买你产品的页面,才能在150美元的产品上卖出18份。</p><p>这720人从哪里来?</p><p>社交媒体、广告、SEO,或者其他形式的达人营销或口碑传播。</p><p>所以,假设你擅长社交媒体(是的,社交媒体是一种技能,不是靠算法运气),你可以:</p><ul><li>每个YouTube视频获得1万到5万次观看</li><li>每月在社交媒体上获得50万到100万次展示</li></ul><p>这意味着,在那么多人里,你只需要有720人点击你的落地页,就能年入100万美元。</p><p><em>在几十万人中要求720人,这真的不算多。</em></p><p><em>当然,大多数人只要能赚到远低于100万美元的钱,也会很开心。</em></p><p>对于那些不习惯这种数额,或者习惯按工资拿钱的人来说,想到事情能这么简单会有点“不切实际”。而这恰恰是你的雇主对你做的事——他们付钱让你执行整个赚钱流程中的某一个特定环节,然后在此基础上赚取数倍的利润。</p><p>但当然,简单不代表容易,老生常谈,我懂。</p><p>要真正精通产品/服务打造、社交媒体营销和文案写作,可能需要5到10年。</p><p>但如果我们用这些原则来训练AI,再喂给它来自传奇营销人的数据,你会惊讶于AI能多好地为你完成这些事。</p><h2 id="如何用ai赚到100万美元" tabindex="-1">如何用AI赚到100万美元 <a class="header-anchor" href="#如何用ai赚到100万美元" aria-label="Permalink to &quot;如何用AI赚到100万美元&quot;">​</a></h2><p>如果你还没读过,<a href="/letters/learn-ai-to-10x-any-other-skill-full-beginner-guide">先去读读我之前那篇讲AI绝对基础知识的信件</a>,里面讲了如何写元提示词(meta prompts)。</p><p>你可以读完这篇之后再去补上那部分。</p><p>现在,我要教你所有关于品牌、营销和内容的知识,以及一种让AI替你完成这些事的方法。</p><h3 id="个人品牌策略" tabindex="-1">个人品牌策略 <a class="header-anchor" href="#个人品牌策略" aria-label="Permalink to &quot;个人品牌策略&quot;">​</a></h3><p>我们要聚焦在社交媒体上,因为:</p><ol><li>它是免费的,而且说实话,我对付费广告的理解不够深,没法教你(而且在社交媒体上测试内容,正是你创造出成功广告而不至于烧掉一大笔钱的方式)</li><li>你可能没有时间做SEO,也没有钱去赞助达人(再说一次,先用社交媒体去测试)</li><li>尽管社交媒体是免费且容易获取的,它可以说是最好的流量来源,而受众=杠杆</li></ol><p>所以你需要这么做:</p><p>首先,前往<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex并开启一个新对话</a>,在“市场(Market)”类别下选择“个人品牌策略(Personal Brand Strategy)”选项。</p><p><img src="'+p+'" alt=""></p><p>按“回车”开始访谈。</p><p>然后,它会引导你完成一系列问题,最终吐出一整套策略,包括:</p><ul><li>你的转变故事、理想目标受众和价值主张的总结</li><li>你的“精通领域”,由一项可变现的技能/兴趣,加上两项互补的技能/兴趣组成</li><li>一份你受众痛点、内容灵感来源和权威建立话题的清单</li><li>一个精简版和一个扩展版的社交媒体简介,可用于不同平台</li><li>一套变现策略,包括可提供的服务、可出售的产品和起始点</li><li>一套内容策略,包括发布日期和一般性建议</li></ul><p><img src="'+i+'" alt=""></p><p>我亲自在Kortex中创建了所有这些AI流程,它们基于我自己的课程、经验和行业最佳实践。</p><p>它们是非常好的起点。</p><p>复制这个提示词的输出结果,把它保存为一个新文档,以便妥善保存。</p><h3 id="客户画像" tabindex="-1">客户画像 <a class="header-anchor" href="#客户画像" aria-label="Permalink to &quot;客户画像&quot;">​</a></h3><p>做市场调研很烦人。</p><p>我一直都很讨厌做这件事,正因如此,我的客户画像总是敷衍了事。</p><p>我从来没觉得自己真正<em>深入挖掘</em>过他们是谁,而我其余的营销工作也因此受到影响。</p><p>有了上面得到的策略,我们需要进一步深入研究你的目标受众。</p><p>我们需要理解他们的人口统计特征、心理特征、购买行为、他们在网上出没的地方,以及更多信息。</p><p>在这一步,创建新提示词时,前往同一个“市场”类别下的“客户画像生成器(Customer Avatar Generator)”。</p><p>用你从个人品牌策略中得到的目标受众描述,填入空白处。</p><p><img src="'+t+'" alt=""></p><p>回答AI提出的所有访谈问题,把你的客户画像保存为一个新文档,并准备好从现在起在其他所有事情中引用它。</p><h3 id="无法拒绝的产品-服务方案" tabindex="-1">无法拒绝的产品/服务方案 <a class="header-anchor" href="#无法拒绝的产品-服务方案" aria-label="Permalink to &quot;无法拒绝的产品/服务方案&quot;">​</a></h3><p>这一步的主要问题在于:</p><ul><li>大多数人不知道自己想卖什么来变现</li><li>如果人们确实知道自己想卖什么,通常也很糟糕,因为它太模糊了</li><li>当他们试图创建一个更有吸引力的方案时,通常是基于猜测而不是数据,而人们对自己在卖的东西也没有信心</li></ul><p>AI很酷的一点是,它拥有的知识几乎相当于整个互联网,而且像Claude这样的某些模型不会像人一样受到自我怀疑和信心不足的影响,而这些恰恰会拖累作品的质量。</p><p>所以,这次也做同样的事。</p><p>前往“无法拒绝的产品/服务方案创建蓝图(Irresistible Offer Creation Blueprint)”,在第一个空白处填入“@customer avatar document”,在第二个空白处,根据你的品牌策略(或你已经计划好的方案),简要描述你想卖的产品或服务。</p><p>同样,回答那些澄清性问题,kAI会吐出一整套完整的方案,包括:</p><ul><li>交付机制(课程、模板、自由职业服务等)</li><li>吸引注意力的大创意</li><li>核心大问题及其放大的痛点</li><li>你受众渴望的可量化结果</li><li>让你的方案与众不同的独特机制</li><li>一般性的特性与好处(你可以也应该修改这些)</li><li>来自亚历克斯·霍尔莫兹(Alex Hormozi)的价值等式分析</li><li>一般性的定位建议,让它变得更好</li></ul><p><img src="'+r+'" alt=""></p><p>同样,把这个保存为你工作区里的一个文档,供下一步使用。</p><h3 id="高转化率的落地页" tabindex="-1">高转化率的落地页 <a class="header-anchor" href="#高转化率的落地页" aria-label="Permalink to &quot;高转化率的落地页&quot;">​</a></h3><p>现在,你所有的营销火力都已经保存在你工作区的文档中了。</p><p>我们需要kAI把所有这些串联起来,写出一篇文笔精良、说服力强的落地页。</p><p>我暂时不会太担心落地页的设计。事实上,转化率最高的落地页往往就是纯粹而有说服力的文字。</p><p>你可以拿着kAI给你的输出结果,在<a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">Stan(一个供创作者托管产品的地方——也是最实惠、功能最丰富的选择)</a>上创建产品,然后把你的落地页文字粘贴进去。</p><p>经过测试后,kAI吐出的文案比我见过的几乎任何创作者都写得更好。大多数创作者甚至根本没想过要去学营销或文案写作,所以仅凭这一点,你就能取得比他们更好的成果(我知道这一点,因为我已经做这行5年了,推出过10多个产品)。</p><p>当我们刚开始接触营销和文案写作时,我们是自己最大的敌人。我们把事情过度复杂化,试图想出最聪明或最有创意的东西,结果却做出了平淡无奇、根本赚不到钱的东西。</p><p>所以,再一次,前往“说服性落地页生成(Persuasive Landing Page Generation)”选项,输入你的目标受众、方案蓝图,以及可选的语气分析。</p><p>看着AI吐出多个标题变体,随后是一篇结构清晰、极具说服力的落地页。</p><p>你可以看到,这里它借用了我的语气分析结果,用哲学式的语气说话可能不是最优选择,但落地页的其余部分相当不错。</p><p><img src="'+o+'" alt=""></p><p>根据需要做一些编辑,但大部分内容应该已经可以直接用了。</p><p>注意:能吐出文案并不意味着你可以忽略<em>测试</em>的必要性。如果你第一次没能赚到钱,那不是AI的错。依然是你的错,因为你没能利用反馈并加以迭代。</p><p>你可以随时回到你的落地页 AI 聊天窗口，跟它说这样的话：</p><p>“这个转化率不太好，你能帮我分析一下原因吗？”</p><p>“我可以在我的报价里加点什么，让它更有吸引力？”</p><p>“重新生成 10 个标题变体，长短都要，这样我可以测试一下。”</p><p>记住，使用 AI 最好的方式是跟它对话，而不是指望它第一次就吐出一个完美的结果。</p><h3 id="帖子、yt-视频、邮件、短视频" tabindex="-1">帖子、YT 视频、邮件、短视频 <a class="header-anchor" href="#帖子、yt-视频、邮件、短视频" aria-label="Permalink to &quot;帖子、YT 视频、邮件、短视频&quot;">​</a></h3><p>现在你已经有了策略、目标受众、报价蓝图，以及落地页。</p><p>现在，你唯一要做的就是把实际产品做出来，然后开始在社交媒体上发帖。</p><p>幸运的是，在“创作”（Create）类别下有这些选项：</p><ul><li>生成 50 个以上的爆款内容创意</li><li>用你自己的语气重新演绎任何一个爆款 YouTube 视频（这个在默认类别下，取消勾选任意类别即可看到）</li><li>为 X、LinkedIn、Threads、IG、YT shorts 或 TikTok 撰写社交帖子或短视频脚本</li><li>写出比大多数创作者更有吸引力的开头钩子（Threads）</li><li>撰写 YouTube 脚本、邮件通讯或文章</li><li>把一个想法转化为 reel、tiktok 或短视频</li></ul><p><img src="'+s+'" alt=""></p><p>除此之外，在“市场”（Market）类别下还有一个“有说服力的广告、邮件和脚本”（Persuasive Ads, Emails, &amp; Scripts）选项，可以撰写不同长度的销售帖子、邮件和广告。它在为 Instagram 和 LinkedIn 帖子撰写植入你产品的文案方面表现也不错。</p><p>现在唯一阻碍你的，就是坐下来真正去做的那份自律。</p><p>如果你在这方面有困难，也许你需要试试“成长”（Growth）类别下的“个人成长顾问”（Personal Growth Advisor）选项。</p><p>所以，是的……这一切都相当疯狂。</p><p>如果你想全部试一遍，<a href="https://kortex.co/" target="_blank" rel="noreferrer">点这里注册 Kortex。</a></p><p>如果你想围绕 Kortex 制作短视频或教程，成为一名联盟推广者，<a href="https://kortex.co/affiliates" target="_blank" rel="noreferrer">你可以在这里操作。</a></p><p>玩得开心点，好好享受这些新模型吧（比如 Llama Scout 和 Maverick、Gemini 2.5 pro，以及其他所有前沿模型）。这样一来，除非你要用 AI 生成图像（我们迟早也会加入这个功能），你就不必再为多个订阅付费了。</p><p>如果你下载了 Kortex 的桌面版本，按下 Ctrl 或 Command+A，就会弹出一个悬浮聊天窗口，这样你随时随地都能在电脑上跟 AI 对话。</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/how-to-actually-make-1-million-with-ai">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',112))])}const q=n(k,[["render",A]]);export{w as __pageData,q as default};
